## 3. Plan de Pruebas Unitarias e Integración (Vitest)
Validamos la lógica de cálculo de Catch Weight y el cumplimiento de esquemas Zod mediante pruebas automatizadas con Vitest.

```typescript
// src/__tests__/b2bHorecaOrder.test.ts
import { describe, it, expect } from 'vitest';
import { b2bHorecaOrderSchema } from '../schemas/b2bHorecaSchema';

describe('SPEC-027: Validación Zod - Portal B2B HORECA', () => {
  const validOrderPayload = {
    tenant_id: 'a0000000-0000-0000-0000-000000000001',
    client_id: 'b0000000-0000-0000-0000-000000000002',
    branch_id: 'c0000000-0000-0000-0000-000000000003',
    delivery_date: new Date(Date.now() + 86400000).toISOString(),
    dian_customer_type: 'RESPONSABLE_IVA' as const,
    lines: [
      {
        product_id: 'd0000000-0000-0000-0000-000000000004',
        ordered_qty: 15.5,
        ordered_unit: 'KG' as const,
        actual_weight_kg: 15.8, // Catch Weight verificado
        unit_price: 28500,
        tax_rate: 19,
      }
    ]
  };

  it('debe validar exitosamente un pedido HORECA completo con Catch Weight', () => {
    const result = b2bHorecaOrderSchema.safeParse(validOrderPayload);
    expect(result.success).toBe(true);
  });

  it('debe fallar si las líneas del pedido están vacías', () => {
    const invalidPayload = { ...validOrderPayload, lines: [] };
    const result = b2bHorecaOrderSchema.safeParse(invalidPayload);
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error.issues[0].message).toContain('al menos una línea');
    }
  });

  it('debe rechazar pesos negativos en Catch Weight', () => {
    const invalidPayload = {
      ...validOrderPayload,
      lines: [{ ...validOrderPayload.lines[0], actual_weight_kg: -2.5 }]
    };
    const result = b2bHorecaOrderSchema.safeParse(invalidPayload);
    expect(result.success).toBe(false);
  });
});
```

