## 4. Plan de Pruebas End-to-End (Playwright)
Prueba E2E para asegurar el flujo completo de creación de pedido B2B HORECA y la renderización sin errores de consola JS (`0 errores JS`).

```typescript
// e2e/b2b-horeca-portal.spec.ts
import { test, expect } from '@playwright/test';

test.describe('SPEC-027: Portal B2B HORECA E2E Flow', () => {
  test('Debe permitir iniciar sesión como cliente HORECA, cotizar y crear pedido con Catch Weight sin errores JS', async ({ page }) => {
    const consoleErrors: string[] = [];
    page.on('console', (msg) => {
      if (msg.type() === 'error') {
        consoleErrors.push(msg.text());
      }
    });

    // 1. Login en el Portal B2B
    await page.goto('/b2b/login');
    await page.fill('input[name="email"]', 'chef@restaurantelacomedia.com');
    await page.fill('input[name="password"]', 'SecurePassword123*');
    await page.click('button[type="submit"]');

    // 2. Verificar redirección al catálogo HORECA
    await expect(page).toHaveURL(/.*\/b2b\/catalog/);

    // 3. Agregar producto al carrito (ej. Salmón fresco por KG)
    await page.click('[data-testid="product-card-salmon"] button.add-to-cart');
    await page.click('[data-testid="cart-drawer-trigger"]');

    // 4. Confirmar checkout y fecha de entrega
    await page.click('button:has-text("Proceder al Pago")');
    await page.fill('input[name="delivery_date"]', '2025-03-30');
    await page.click('button:has-text("Confirmar Pedido B2B")');

    // 5. Validar éxito de la transacción
    await expect(page.locator('.toast-success')).toBeVisible();
    await expect(page).toHaveURL(/.*\/b2b\/orders\/success/);

    // 6. Aserción estricta de Cero Errores de Consola JS
    expect(consoleErrors).toEqual([]);
  });
});
```

